import { isRecord } from "../security/record.js";
import { createHash } from "node:crypto";
import { redactKnownSecrets } from "../security/env.js";
/** Bounded metadata projection. Never retain model prose, tool arguments or HTTP bodies. */
export class RunDiagnostics {
    level;
    log;
    deadlineMs;
    started = Date.now();
    lastActivity = this.started;
    events = [];
    dropped = 0;
    pendingError = "";
    secrets;
    constructor(level, log, secrets = [], deadlineMs) {
        this.level = level;
        this.log = log;
        this.deadlineMs = deadlineMs;
        this.secrets = [...secrets];
    }
    addSecrets(secrets) {
        this.secrets.push(...secrets);
    }
    event(phase, details = {}, source = "controller") {
        if (this.level === "off")
            return;
        this.lastActivity = Date.now();
        const safe = (value) => redactKnownSecrets(value, this.secrets)
            .replace(/[^A-Za-z0-9_.: -]/gu, "_")
            .slice(0, 100);
        const event = {
            source,
            phase: safe(phase),
            elapsedMs: this.lastActivity - this.started,
            ...(details.name === undefined ? {} : { name: safe(details.name) }),
            ...(details.call === undefined
                ? {}
                : { call: createHash("sha256").update(details.call).digest("hex").slice(0, 16) }),
            ...(details.status === undefined ? {} : { status: details.status }),
        };
        if (this.events.length === 1000) {
            this.events.shift();
            this.dropped++;
        }
        this.events.push(event);
        try {
            this.log(`[dsh] ${source} ${event.phase}${event.name ? ` ${event.name}` : ""} +${String(event.elapsedMs)}ms`);
        }
        catch {
            /* Diagnostics cannot replace business results. */
        }
    }
    heartbeat() {
        if (this.level !== "off")
            this.log(`[dsh] waiting at ${this.events.at(-1)?.phase ?? "startup"}; last activity ${String(Date.now() - this.lastActivity)}ms ago; elapsed ${String(Date.now() - this.started)}ms`);
    }
    async phase(name, run) {
        this.event(`${name}.start`);
        try {
            const result = await run();
            this.event(`${name}.end`);
            return result;
        }
        catch (error) {
            this.event(`${name}.error`);
            throw error;
        }
    }
    resetStream() {
        this.pendingError = "";
    }
    stderr(chunk) {
        this.pendingError = (this.pendingError + chunk.toString("utf8")).slice(-65536);
        const lines = this.pendingError.split("\n");
        this.pendingError = lines.pop() ?? "";
        for (const line of lines)
            if (line.startsWith("DSH_DIAGNOSTIC ")) {
                try {
                    const row = JSON.parse(line.slice(15));
                    if (isRecord(row) &&
                        "phase" in row &&
                        typeof row.phase === "string" &&
                        /^(?:profile|loader)\.[a-z-]+$/.test(row.phase))
                        this.event(row.phase, typeof row.name === "string" ? { name: row.name } : {}, "worker");
                }
                catch {
                    /* Ignore malformed diagnostics. */
                }
            }
    }
    observeHeadless(value) {
        if (!isRecord(value))
            return;
        const row = value;
        if (row.type === "status" &&
            ["turn_start", "step_start", "step_end", "turn_end"].includes(String(row.phase))) {
            this.event(String(row.phase), {}, "worker");
        }
        else if (row.type === "tool_call" &&
            typeof row.tool === "string" &&
            typeof row.callId === "string")
            this.event("tool.start", { name: row.tool, call: row.callId }, "worker");
        else if (row.type === "tool_result" && typeof row.callId === "string")
            this.event(row.status === "error" ? "tool.error" : "tool.end", { call: row.callId }, "worker");
        else if (row.type === "session" || row.type === "final")
            this.event(row.type, {}, "worker");
        else if (row.type === "text" || row.type === "thinking")
            this.lastActivity = Date.now();
    }
    snapshot() {
        return {
            level: this.level,
            events: [...this.events],
            dropped: this.dropped,
            elapsedMs: Date.now() - this.started,
            lastActivityMs: Date.now() - this.lastActivity,
            ...(this.deadlineMs === undefined
                ? {}
                : { remainingMs: Math.max(0, this.deadlineMs - Date.now()) }),
        };
    }
}
